function ib.weatherStrength(Oo)
local Po=ib.fx(Oo)
local Qo=Po.dmg/Po.cd/Po.hp/Po.speed*(1+(Po.range-1)/2)
for Ro,So in pairs(Po.kinds)do
Qo=Qo*(1+W.rogueShare(Ro)*So)
end
if Po.ice>0 then
local To=W.rogueShare(Ecd[1708])
Qo=Qo*(To+(1-To)/(1-Po.ice+Po.ice/db.modFactor(Ecd[1824])))
end
if Po.fly>0 then
Qo=Qo*(1-Po.fly*0.5)
end
if Po.noCC then
Qo=Qo*0.95
end
if Po.shroud then
Qo=Qo*0.9
end
return Qo
end
function ib.cardGems(Uo,Vo)
