for Yo,Zo in pairs(type(Uo.effects)==Ecd[1577]and Uo.effects or{})do
if type(Zo)==Ecd[1577]then
local _o=tonumber(Zo.amount)or 0
if Zo.type==Ecd[1825]then
Wo=Wo+math.abs(_o)*Xo*M.pearlValue
elseif Zo.type==Ecd[1826]then
local ap,bp=pcall(U.rewardValue,Zo.reward)
if ap then
Wo=Wo+(tonumber(bp)or 0)
end
elseif Zo.type==Ecd[1827]then
Wo=Wo+_o*ib.STARFALL_GEMS
elseif Zo.type==Ecd[1828]then
Wo=Wo+_o*100
end
end
end
if Uo.option_type==Ecd[1829]then
Wo=Wo+ib.HARD_GEMS
end
if Uo.weather then
local cp=Uo.weather~=ib.weatherNow()
if cp and Uo.weather==Ecd[1776]then
Wo=Wo+ib.starfallRemnants(50-(tonumber(Vo)or 0))*(L.ITEM_VALUE.star_remnant_limited or 25)
end
local dp=ib.board()
if cp and dp and Uo.weather~=Ecd[1782]and not dp.weathers[Uo.weather]then
Wo=Wo+(1000+5000*M.pearlValue+50*(L.ITEM_VALUE.star_remnant_limited or 25))/ib.WEATHERS
end
end
return Wo
end
