function hb.relicWorth(mM,nM)
local oM=nM._unique_item_data and nM._unique_item_data._unique_relic_data
if not oM then
return 0
end
local pM=L.Items[nM.item_id]or{}
local qM,rM=R.types(mM.unit_id)
if pM.main_damage_type and pM.main_damage_type~=Ecd[2220]and pM.main_damage_type~=rM then
return 0
end
local sM,tM=0,0
for uM,vM in pairs(oM._core_damage_type_buffs or{})do
if qM[vM.damage_type]then
sM=sM+(tonumber(vM.mul)or 0)+(tonumber(vM.add_upg)or 0)*0.01+(tonumber(vM.pen)or 0)*0.001
tM=tM+(tonumber(vM.crit)or 0)
end
end
sM=sM+tM*0.5
local wM=R.rows(mM.unit_id)
local xM=wM and wM[wM.max]
local yM=(xM and tonumber(xM.cd)or 0)*R.mult(mM,Ecd[1730])
for zM,AM in pairs(oM._unique_relic_effects or{})do
local BM=type(AM.params)==Ecd[1577]and AM.params or{}
if AM.id==Ecd[2221]then
local CM=math.min(1,(tonumber(BM.extra_damage)or 0)*yM/math.max(1,tonumber(BM.time_interval)or 40))
local DM=R.DRONES and R.DRONES[mM.unit_id]
if DM and DM.late and yM>0 then
local EM=1/yM
CM=CM*EM/(EM+(tonumber(DM.max)or 0)*(tonumber(DM.late.dmg)or 0)*(tonumber(DM.hits)or 1)/math.max(0.1,tonumber(DM.late.cd)or 4))
end
sM=sM+CM
elseif AM.id==Ecd[2222]then
sM=sM+(tonumber(BM.dmg_buff)or 0)*0.25
elseif AM.id==Ecd[2223]then
sM=sM+(tonumber(BM.dmg_buff)or 0)*tM
elseif AM.id==Ecd[2224]then
if qM.magic then
sM=0
else
sM=sM+(tonumber(BM.dmg_buff)or 0)*0.3
end
elseif AM.id==Ecd[2225]then
if qM.water_damage then
sM=sM+0.05
end
end
end
return sM
end
function hb.relicPlan()
