local wN=vN and hb.relicWorth(sN.e.u,vN)*sN.share*100 or 0
table.insert(qN,string.format(Ecd[2228],R.name(sN.e.id),tN and(L.Items[tN.item_id]or{}).name or Ecd[1864],uN,vN and(L.Items[vN.item_id]or{}).name or Ecd[1864],wN))
end
return dN,eN-pN,qN,KM
end
