function cb.upgradeGain(qcb,rcb,scb,tcb,ucb,vcb)
local wcb,xcb=rcb[scb],rcb[scb+1]
local ycb=(wcb.cd>0 and wcb.damage/wcb.cd or 0)
local zcb=(xcb.cd>0 and xcb.damage/xcb.cd or 0)*R.aoe(xcb.atk,xcb.range)/math.max(0.3,R.aoe(wcb.atk,wcb.range))
local Acb=ycb>0 and qcb*(zcb/ycb-1)or(vcb or 0)
local Bcb=rcb[scb+2]
if Bcb and scb+1<rcb.max and Bcb.cd>0 and xcb.cd>0 and ycb>0 then
local Ccb=qcb*((Bcb.damage/Bcb.cd)/ycb-1)
local Dcb=tcb+Bcb.cost*ucb
if Ccb/Dcb>Acb/tcb then
Acb=Acb+(Ccb/Dcb*tcb-Acb)*0.5
end
end
local Ecb=(xcb.range or 0)>(wcb.range or 0)and(1+((xcb.range-wcb.range)/math.max(1,wcb.range)))or 1
return math.max(0,Acb)*Ecb
end
function cb.dpsFor(Fcb,Gcb)
if Gcb<=0 then
return 0
end
local Hcb={}
for Icb,Jcb in ipairs(Fcb)do
if not Jcb.farm and Jcb.gain>0 then
table.insert(Hcb,Jcb)
end
end
table.sort(Hcb,function(Kcb,Lcb)
return Kcb.gain/Kcb.cost>Lcb.gain/Lcb.cost
end)
local Mcb,Ncb=0,0
for Ocb,Pcb in ipairs(Hcb)do
if Gcb<=0 then
break
end
Ncb=Pcb.gain/Pcb.cost
local Qcb=math.min(1,Gcb/Pcb.cost)
Mcb=Mcb+Pcb.gain*Qcb
Gcb=Gcb-Pcb.cost*Qcb
end
return Mcb+math.max(0,Gcb)*Ncb*0.7
end
function cb.shieldDps(Rcb,Scb,Tcb,Ucb,Vcb,Wcb,Xcb)
if(Ucb or 0)<=0 or(Rcb or 0)<=0 or(Vcb or 0)<=0 then
return Rcb or 0
end
Scb,Tcb,Wcb=math.max(0.3,Scb or 2),math.max(1,Tcb or 1),Wcb or 1
local Ycb=Rcb*Wcb*Scb/Tcb
return Vcb*Tcb/((Ucb/math.max(1,Xcb or 1)+math.max(1,Vcb/Ycb))*Scb)/Wcb
end
function cb.shieldGain(Zcb,_cb,adb,bdb,cdb,ddb,edb,fdb)
local gdb,hdb=R.attackInfo(_cb.atk,_cb.range),R.attackInfo(bdb.atk,bdb.range)
local idb=cb.shieldDps(Zcb,(tonumber(_cb.cd)or 2)*(edb or 1),gdb.n,cdb,ddb,fdb,gdb.hits)
local jdb=cb.shieldDps(adb,(tonumber(bdb.cd)or 2)*(edb or 1),hdb.n,cdb,ddb,fdb,hdb.hits)
local kdb=math.max(0,((tonumber(bdb.range)or 0)-(tonumber(_cb.range)or 0))/math.max(1,tonumber(_cb.range)or 1))
return math.max(0,jdb-idb)+idb*kdb
end
function cb.shieldWork(ldb,mdb,ndb,odb,pdb,qdb,rdb,sdb,tdb)
if(odb or 0)<=0 then
return 0
end
local udb=3*odb*(pdb or 1)/math.max(1,qdb or 20)
if(ndb or 0)>=udb then
return 0
end
return math.max(1,ldb or 1)*math.max(1,tdb or 1)/math.max(0.3,mdb or 2)*math.min(rdb or 0,sdb or 0)
end
function cb.holdGain(vdb,wdb,xdb,ydb)
if not vdb or(wdb or 0)<=0 then
return 0
end
local zdb,Adb=tonumber(vdb.stun)or 0,tonumber(vdb.slowTime)or 0
if zdb<=0 and Adb<=0 then
return 0
end
local Bdb,Cdb=zdb>0 and zdb or Adb,zdb>0 and 1 or(tonumber(vdb.slowPct)or 0.3)
local Ddb=Cdb*Bdb/(Bdb+(tonumber(vdb.ccCd)or 8))
local Edb=Ddb/math.max(0.1,1-Ddb)
return wdb*Edb*Q.clamp(xdb or 0.5,0,1)*math.min(1,(tonumber(vdb.n)or 1)/2)/(1+(ydb or 0))
end
function cb.bleedGain(Fdb,Gdb,Hdb,Idb)
if(Fdb or 0)<=0 then
return 0
end
local Jdb=Gdb or 0
for Kdb,Ldb in ipairs(Hdb or{})do
Jdb=math.max(Jdb,(tonumber(Ldb.hp)or 0)*0.5)
end
return Fdb*Jdb*(Idb and 0.5 or 1)
end
function cb.bleedShare(Mdb,Ndb,Odb,Pdb)
if Mdb<=0 or not Ndb then
return 0
end
if Pdb then
return Ndb==0 and Mdb or Mdb/(Ndb+1)
end
return Odb<Ndb and Mdb/(Ndb-Odb)or 0
end
function cb.keepsUp(Qdb,Rdb,Sdb,Tdb,Udb)
local Vdb=Qdb.coming
if not(Vdb and#Vdb>0 and Qdb.waveSec)then
return true
end
local Wdb=Qdb.eff or 1
local Xdb=Qdb.money-Sdb
local Ydb=(Qdb.teamDps or 0)*(Qdb.shieldK or 1)+(Tdb or 0)*Wdb+cb.dpsFor(Rdb,math.max(0,Xdb))*Wdb
local Zdb=(Qdb.farmNow or 0)+(Udb or 0)
local _db=(Qdb.roadSec or 130)*Q.clamp(Qdb.cover or 0.6,0.1,1)
local aeb=Qdb.hpAlive or 0
for beb,ceb in ipairs(Vdb)do
aeb=math.max(0,aeb+ceb.hp-Ydb*Qdb.waveSec)
local deb=Ydb*_db
if aeb>deb then
return false,beb,deb/math.max(1,aeb)
end
if beb< #Vdb then
Ydb=Ydb+cb.dpsFor(Rdb,(ceb.reward or 0)+Zdb)*Wdb*(0.85^beb)
end
end
return true
end
function cb.decide(eeb,feb)
local geb=Q.clamp(feb.cover or 0.6,0.1,1)
local heb=math.max(M.clearSec,0.7*(feb.roadSec or 50)*geb)
local ieb=(feb.clearSec or 0)>heb
feb.piling=feb.piling and ieb
local jeb=feb.attackers>0 and feb.pressure<math.min(M.safeReach,geb*0.75)and not feb.piling and not ieb
local keb=feb.pressure>=math.min(M.dangerReach,geb*0.9)or(feb.piling and feb.enemies>=18)
local leb,meb
for neb,oeb in ipairs(eeb)do
if oeb.farm then
if M.farmUnits and oeb.gain>0 then
oeb.payback=oeb.cost/oeb.gain
if feb.left-1>=oeb.payback+(feb.farmSpare or M.farmSpare)and(not leb or oeb.payback<leb.payback)then
leb=oeb
end
end
else
oeb.ratio=oeb.gain/math.max(1,oeb.cost)
if not meb or oeb.ratio>meb.ratio then
meb=oeb
end
end
end
if feb.leak and feb.attackers>0 then
local peb
for qeb,reb in ipairs(eeb)do
local seb=not feb.airLeak or(reb.e and W.cardAir(reb.e.id))
if reb.place and not reb.farm and seb and reb.cost<=feb.money and not(reb.e and R.allyBuff(reb.e.id))and(not peb or reb.gain>peb.gain)then
peb=reb
end
end
if peb then
return peb,string.format(Ecd[2799],math.floor(feb.leak*100))
end
end
local teb=feb.future<feb.wantLeft*1.1
local ueb,veb,web=true,nil,nil
if leb then
