local pib=Efb(L.LU.Infinite.infinite_get_normal_unit_chance,oib,cib)or 0
if pib>0 then
table.insert(lib,{k=nib,c=pib})
mib=mib+pib
end
end
end
table.sort(lib,function(qib,rib)
return qib.k<rib.k
end)
local sib,tib=math.floor(kib+0.5),0
for uib,vib in ipairs(lib)do
local wib=(uib== #lib)and math.max(0,sib-tib)or math.floor(sib*vib.c/mib+0.5)
for xib=1,wib do
local yib=db.enemy(bib,vib.k,cib)
if yib then
table.insert(eib,yib)
end
end
tib=tib+wib
end
local zib=bib.ld._infinite_bound_level and cib==bib.total
if zib then
local Aib,Bib={},0
for Cib,Dib in pairs(bib.configs)do
if type(Dib)==Ecd[1577]and tonumber(Dib.spawn_tier_boss)and(Efb(L.LU.Infinite.infinite_get_boss_unit_chance,Dib,cib)or 0)>0 then
local Eib=db.baseStats(bib,Cib)
if Eib then
table.insert(Aib,{k=Cib,hp=Eib,tier=tonumber(Dib.spawn_tier_boss)})
Bib=Bib+Eib
