local Jib=Bib/ #Aib
for Kib,Lib in ipairs(Aib)do
if math.abs(Lib.hp-Jib)<math.abs(Iib.hp-Jib)then
Iib=Lib
end
end
end
if Iib then
local Mib=db.enemy(bib,Iib.k,cib)
if Mib then
Mib.boss=true
table.insert(eib,Mib)
end
end
elseif cib%bib.bossEvery==0 and not bib.skip[tostring(cib)]then
local Nib=math.max(1,math.min(6,math.floor(cib/bib.bossEvery)))
for Oib,Pib in pairs(bib.configs)do
if type(Pib)==Ecd[1577]and tonumber(Pib.spawn_tier_boss)==Nib then
local Qib=db.enemy(bib,Oib,cib)
if Qib then
Qib.boss=true
table.insert(eib,Qib)
end
break
end
end
end
if bib.final and tonumber(bib.final.wave)==cib and bib.final.cfg then
local Rib=db.enemy(bib,bib.final.cfg,cib)
if Rib then
Rib.boss=true
table.insert(eib,Rib)
end
end
end
local Sib=bib.fx and bib.fx.starfall
local Tib=Sib and bib.cfgById and bib.cfgById.star_golem_1
if Tib and(tonumber(Sib.perWave)or 0)>0 then
if cib<=1 then
bib.starAcc=0
end
bib.starAcc=(bib.starAcc or 0)+Sib.perWave
while bib.starAcc>=1 do
local Uib=db.enemy(bib,Tib,cib)
if Uib then
local Vib=tonumber(Sib.hpK)or 1
Uib.hp,Uib.max=Uib.hp*Vib,Uib.max*Vib
table.insert(eib,Uib)
end
bib.starAcc=bib.starAcc-1
