end
local Pwb=Kwb(Ewb)>0
local function Qwb(Rwb)
local Swb=0
for Twb,Uwb in ipairs(Rwb)do
if not R.isFarm(Uwb.unit_id)and not R.allyBuff(Uwb.unit_id)then
Swb=Swb+R.cap(Uwb)
end
end
return Swb
end
local Vwb
while#Hwb<6 do
local Wwb,Xwb
local Ywb=Pwb and Kwb(Hwb)==0
for Zwb,_wb in ipairs(Ewb)do
local axb=false
for bxb,cxb in ipairs(Hwb)do
if cxb.unit_id==_wb.unit_id then
axb=true
end
end
if not axb and(not Ywb or R.isFarm(_wb.unit_id))then
local dxb=table.clone(Hwb)
table.insert(dxb,_wb)
local exb=db.run(Cwb,db.teamFrom(dxb,Cwb.map),{hpMul=Iwb})
local fxb=db.objective(exb)
if not Xwb or fxb>Xwb then
Wwb,Xwb,Vwb=_wb,fxb,exb
end
end
end
if not Wwb then
break
end
table.insert(Hwb,Wwb)
end
if Pwb and Kwb(Hwb)==0 then
local gxb,hxb
for ixb=1,#Hwb do
for jxb,kxb in ipairs(Ewb)do
if R.isFarm(kxb.unit_id)then
local lxb=table.clone(Hwb)
lxb[ixb]=kxb
local mxb=db.run(Cwb,db.teamFrom(lxb,Cwb.map),{hpMul=Iwb})
local nxb=db.objective(mxb)
