gxb,hxb,Vwb=lxb,nxb,mxb
end
end
end
end
if gxb then
Hwb=gxb
end
end
local function oxb(pxb,qxb)
local rxb=db.teamFrom(pxb,Cwb.map)
return(db.objective(qxb)+db.objective(db.run(Cwb,rxb,{hpMul=Iwb*0.92}))+db.objective(db.run(Cwb,rxb,{hpMul=Iwb*1.08})))/3
end
local sxb,txb=Vwb or Jwb,oxb(Hwb,Vwb or Jwb)
if type(Ewb.rest)==Ecd[1577]and#Ewb.rest>0 then
local uxb,vxb
for wxb,xxb in ipairs(Hwb)do
if not R.isFarm(xxb.unit_id)and not R.allyBuff(xxb.unit_id)then
local yxb,zxb=pcall(R.score,xxb,Cwb.mod)
zxb=(yxb and zxb or 0)*R.skinMul(xxb,Cwb.skinSet)
if not vxb or zxb<vxb then
uxb,vxb=wxb,zxb
end
end
end
if uxb then
local Axb,Bxb={},Q.now()
for Cxb,Dxb in ipairs(Ewb.rest)do
if Q.now()-Bxb>5 then
break
end
local Exb=false
for Fxb,Gxb in ipairs(Hwb)do
if Gxb.unit_id==Dxb.unit_id then
Exb=true
end
end
if not Exb then
local Hxb=table.clone(Hwb)
Hxb[uxb]=Dxb
table.insert(Axb,{u=Dxb,o=db.objective(db.run(Cwb,db.teamFrom(Hxb,Cwb.map),{hpMul=Iwb}))})
end
end
table.sort(Axb,function(Ixb,Jxb)
return Ixb.o>Jxb.o
end)
Ewb=table.clone(Ewb)
for Kxb=1,math.min(4,#Axb)do
table.insert(Ewb,1,Axb[Kxb].u)
end
Gwb=Gwb+(Q.now()-Bxb)
end
end
for Lxb=1,2 do
local Mxb=false
for Nxb=1,#Hwb do
for Oxb,Pxb in ipairs(Ewb)do
if Q.now()-Gwb>Fwb then
return Hwb,sxb,Iwb,Jwb
end
local Qxb=false
for Rxb,Sxb in ipairs(Hwb)do
if Sxb.unit_id==Pxb.unit_id then
Qxb=true
end
end
if not Qxb then
local Txb=table.clone(Hwb)
Txb[Nxb]=Pxb
if(not Pwb or Kwb(Txb)>0)and Qwb(Txb)>=math.min(8,Qwb(Hwb))then
local Uxb=db.run(Cwb,db.teamFrom(Txb,Cwb.map),{hpMul=Iwb})
local Vxb=db.objective(Uxb)
if Vxb>txb+1 then
Vxb=oxb(Txb,Uxb)
if Vxb>txb+1 then
Hwb,txb,sxb,Mxb=Txb,Vxb,Uxb,true
end
end
end
end
end
end
if not Mxb then
break
end
end
return Hwb,sxb,Iwb,Jwb
end
