function W.buildPath()
W.samples={}
local qLb=L.PATH and L.PATH.PATH_CACHE and L.PATH.PATH_CACHE[workspace._BASES.pve]
if not qLb then
return
end
for rLb,sLb in pairs(qLb)do
if not(L.PATH.HIDDEN_MOCK_LANES and L.PATH.HIDDEN_MOCK_LANES[rLb.Name])then
local tLb={}
for uLb,vLb in ipairs(sLb.points or{})do
table.insert(tLb,vLb.part.Position)
end
local wLb=0
for xLb=2,#tLb do
wLb=wLb+(tLb[xLb]-tLb[xLb-1]).Magnitude
end
local yLb=0
for zLb=2,#tLb do
local ALb,BLb=tLb[zLb-1],tLb[zLb]
local CLb=(BLb-ALb).Magnitude
local DLb=math.max(1,math.floor(CLb/2))
for ELb=0,DLb-1 do
local FLb=ALb:Lerp(BLb,ELb/DLb)
table.insert(W.samples,{pos=FLb,prog=(yLb+CLb*ELb/DLb)/math.max(1,wLb),lane=rLb.Name})
end
yLb=yLb+CLb
end
if tLb[#tLb]then
table.insert(W.samples,{pos=tLb[#tLb],prog=1,lane=rLb.Name})
end
end
end
W.laneCut,W.laneWant,W.laneFirst=nil,nil,nil
