function W.learn()
local wec=W.calRun and W.calRun.potBy
if type(wec)~=Ecd[1577]then
return
end
pcall(W.sampleHelpers,true)
local xec={}
for yec,zec in pairs(W.ownDealt or{})do
if not R.isFarm(zec.id)then
xec[zec.id]=(xec[zec.id]or 0)+(tonumber(zec.v)or 0)
end
end
for Aec,Bec in pairs(W.helperDealt or{})do
if Bec.owner and R.SUMMONER[Bec.owner]then
xec[Bec.owner]=(xec[Bec.owner]or 0)+(tonumber(Bec.v)or 0)
end
end
local Cec,Dec=0,0
for Eec,Fec in pairs(wec)do
if Fec>0 then
Cec=Cec+(xec[Eec]or 0)
Dec=Dec+Fec
end
end
if Cec<=0 or Dec<=0 then
return
end
local Gec=Cec/Dec
W.lastEff={}
for Hec,Iec in pairs(wec)do
if Iec>0 and Iec/Dec>0.02 then
local Jec=N.learn[Hec]or{eff=1,n=0}
local Kec=math.max(0.02,0.25*math.sqrt(30/(30+Jec.n)))
local Lec=Q.clamp(((xec[Hec]or 0)/Iec)/Gec,0.3,3)
W.lastEff[Hec]=math.floor(Lec*1000+0.5)/1000
Jec.eff=Jec.eff+(Lec-Jec.eff)*Kec
Jec.n=Jec.n+1
N.learn[Hec]=Jec
end
end
local Mec=R.mapKey((W.info and W.info.map)or(W.ld and W.ld.map))
if Mec and next(W.lastEff)then
N.mapLearn=type(N.mapLearn)==Ecd[1577]and N.mapLearn or{}
local Nec=type(N.mapLearn[Mec])==Ecd[1577]and N.mapLearn[Mec]or{}
for Oec,Pec in pairs(W.lastEff)do
local Qec=type(Nec[Oec])==Ecd[1577]and Nec[Oec]or{eff=Pec,n=0}
local Rec=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(Qec.n)or 0))))
Qec.eff=(tonumber(Qec.n)or 0)==0 and Pec or((tonumber(Qec.eff)or Pec)+(Pec-(tonumber(Qec.eff)or Pec))*Rec)
Qec.n=(tonumber(Qec.n)or 0)+1
Nec[Oec]=Qec
end
Nec._at=os.time()
N.mapLearn[Mec]=Nec
if Q.count(N.mapLearn)>80 then
local Sec,Tec
for Uec,Vec in pairs(N.mapLearn)do
if not Tec or(tonumber(Vec._at)or 0)<Tec then
Sec,Tec=Uec,tonumber(Vec._at)or 0
end
end
N.mapLearn[Sec]=nil
end
end
end
