function jb.evoProgress(dRc)
if dRc.ready then
return 1
end
local eRc,fRc,gRc=0,0,{}
for hRc,iRc in ipairs(dRc.plans or{})do
local jRc=tonumber(iRc.need)or 0
if iRc.item then
gRc[iRc.item]=true
end
if jRc>0 then
eRc=eRc+math.min(1,(tonumber(iRc.have)or 0)/jRc)
fRc=fRc+1
end
end
for kRc,lRc in ipairs(dRc.items or{})do
if not gRc[lRc.id]then
eRc=eRc+1
fRc=fRc+1
end
end
return fRc>0 and eRc/fRc or 0
end
